package com.learnagent.weekly;import com.learnagent.notification.*;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/weekly-reviews")public class WeeklyReviewController{private final WeeklyReviewService service;private final NotificationService notifications;public WeeklyReviewController(WeeklyReviewService service,NotificationService notifications){this.service=service;this.notifications=notifications;}@GetMapping public List<WeeklyReviewService.WeeklyReviewView>list(){return service.list();}@GetMapping("/latest")public ResponseEntity<WeeklyReviewService.WeeklyReviewView>latest(){var review=service.latest();return review==null?ResponseEntity.noContent().build():ResponseEntity.ok(review);}@GetMapping("/{id}")public WeeklyReviewService.WeeklyReviewView get(@PathVariable UUID id){return service.get(id);}@PostMapping("/generate")public ResponseEntity<WeeklyReviewService.WeeklyReviewView>generate(){var review=service.generate();notifications.create(NotificationType.WEEKLY_REVIEW,"本周学习周报已生成","查看本周进展、薄弱点与下周计划。","/weekly-review","WEEKLY_REVIEW",review.id(),"weekly-"+review.periodStart());return ResponseEntity.status(HttpStatus.CREATED).body(review);}}
